import * as THREE from 'three/webgpu';
import { Fn, uv, vec3, vec4, float, mix, step, smoothstep, uniform, positionLocal, normalLocal, dot, mx_fractal_noise_float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'gradient-cta-object';

  const W = 2.6, H = 0.68, R = 0.08, DEPTH = 0.06;

  // rounded rect shape for extruded button body
  const shape = new THREE.Shape();
  const x = -W / 2, y = -H / 2;
  shape.moveTo(x + R, y);
  shape.lineTo(x + W - R, y);
  shape.quadraticCurveTo(x + W, y, x + W, y + R);
  shape.lineTo(x + W, y + H - R);
  shape.quadraticCurveTo(x + W, y + H, x + W - R, y + H);
  shape.lineTo(x + R, y + H);
  shape.quadraticCurveTo(x, y + H, x, y + H - R);
  shape.lineTo(x, y + R);
  shape.quadraticCurveTo(x, y, x + R, y);

  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.02,
    bevelSegments: 2,
    curveSegments: 8,
  });
  geometry.center();

  const stops = (config.visualSpec?.colors?.gradientStops) || [
    { at: 0, hex: '#ff4450' }, { at: 0.55, hex: '#ff2a38' }, { at: 1, hex: '#c1121f' },
  ];
  const cTop = uniform(new THREE.Color(stops[0].hex));
  const cMid = uniform(new THREE.Color(stops[1].hex));
  const cBot = uniform(new THREE.Color(stops[2].hex));

  const material = new THREE.MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
  });

  const vY = positionLocal.y.add(float(H / 2)).div(float(H)).clamp(0, 1);

  const gradTop = mix(cBot, cMid, smoothstep(float(0.0), float(0.55), vY));
  const gradFull = mix(gradTop, cTop, smoothstep(float(0.55), float(1.0), vY));
  const seam = step(float(0.495), vY).sub(step(float(0.505), vY));
  const seamColor = vec3(0.0, 0.0, 0.0);
  const finalColor = mix(gradFull, seamColor, seam.mul(0.6));

  material.colorNode = vec4(finalColor, 1.0);

  const edgeIntensity = uniform(1.6);
  const accent = uniform(new THREE.Color(config.visualSpec?.colors?.accent || '#ff2a38'));
  const rim = float(1.0).sub(normalLocal.z.abs()).pow(2.0).clamp(0, 1);
  material.emissiveNode = accent.mul(rim).mul(edgeIntensity).mul(0.15);

  const buttonMesh = new THREE.Mesh(geometry, material);
  buttonMesh.name = 'cta-button-body';
  group.add(buttonMesh);

  // contact shadow plane
  const shadowGeo = new THREE.PlaneGeometry(W * 0.9, H * 0.9);
  const shadowMat = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.y = -0.08 - H / 2;
  shadowMesh.name = 'cta-contact-shadow';
  group.add(shadowMesh);

  // label text
  let labelMesh = null;
  let captionMesh = null;
  const typo = config.visualSpec?.typography || {};
  const ctaTypo = typo['cta-label'] || { fontSize: 20, letterSpacing: 0.08 };
  const capTypo = typo['caption'] || { fontSize: 9, letterSpacing: 0.12 };

  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    labelMesh = ctx.fontAtlas.createText({
      text: 'BEGIN COMMISSION',
      font: 'JetBrains Mono',
      weight: 700,
      size: 0.11,
      color: '#e8ecf2',
      letterSpacing: ctaTypo.letterSpacing,
      align: 'center',
    });
    labelMesh.position.set(0, 0, DEPTH / 2 + 0.005);
    labelMesh.name = 'cta-label';
    group.add(labelMesh);

    captionMesh = ctx.fontAtlas.createText({
      text: 'NO DEPOSIT REQUIRED',
      font: 'JetBrains Mono',
      weight: 400,
      size: 0.05,
      color: '#e8ecf2',
      letterSpacing: capTypo.letterSpacing,
      align: 'center',
    });
    captionMesh.position.set(0, -H / 2 - 0.25, 0.01);
    captionMesh.name = 'cta-caption';
    group.add(captionMesh);
  }

  const pos = config.scenePlacement?.position || [0, 0, 0];
  const rot = config.scenePlacement?.rotation || [0, 0, 0];
  const scl = config.scenePlacement?.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // mount weighted-settle
  group.scale.setScalar(scl[0] * 1.04);
  const mountTl = gsap.timeline();
  mountTl.to(group.scale, {
    x: scl[0], y: scl[1], z: scl[2],
    duration: 0.9,
    ease: 'power4.out',
  });

  let pressTl = null;
  let hoverTl = null;

  const onPointerOver = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(buttonMesh.position, { z: 0.06, duration: 0.18, ease: 'power2.out' });
    hoverTl.to(edgeIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
  };

  const onPointerOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(buttonMesh.position, { z: 0.0, duration: 0.18, ease: 'power2.out' });
    hoverTl.to(edgeIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
  };

  const onPointerDown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: scl[0] * 0.97, y: scl[1] * 0.97, z: scl[2] * 0.97, duration: 0.12, ease: 'back.in(1.7)' });
    pressTl.to(shadowMat, { opacity: 0.2, duration: 0.12 }, 0);
  };

  const onPointerUp = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: scl[0], y: scl[1], z: scl[2], duration: 0.12, ease: 'back.out(1.7)' });
    pressTl.to(shadowMat, { opacity: 0.35, duration: 0.12 }, 0);
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
  };

  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn) fn(group, primitive.params);
    });
  }

  group.userData.cleanup = () => {
    mountTl && mountTl.kill();
    hoverTl && hoverTl.kill();
    pressTl && pressTl.kill();
    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (labelMesh) {
      labelMesh.geometry?.dispose();
      labelMesh.material?.dispose();
    }
    if (captionMesh) {
      captionMesh.geometry?.dispose();
      captionMesh.material?.dispose();
    }
  };

  return group;
}
